import sys

def main():
    data = sys.stdin.read().split()
    n, m, T = int(data[0]), int(data[1]), int(data[2])
    g = data[3:3 + n]
    MOD = 10**9 + 7
    INF = 10**9
    d = [[0 if c == '0' else INF for c in row] for row in g]
    for i in range(n):
        row = d[i]
        up = d[i - 1] if i else None
        for j in range(m):
            v = row[j]
            if up is not None and up[j] + 1 < v:
                v = up[j] + 1
            if j and row[j - 1] + 1 < v:
                v = row[j - 1] + 1
            row[j] = v
    for i in range(n - 1, -1, -1):
        row = d[i]
        dn = d[i + 1] if i + 1 < n else None
        for j in range(m - 1, -1, -1):
            v = row[j]
            if dn is not None and dn[j] + 1 < v:
                v = dn[j] + 1
            if j + 1 < m and row[j + 1] + 1 < v:
                v = row[j + 1] + 1
            row[j] = v
    prev = [0] * m
    for i in range(n):
        cur = [0] * m
        dr = d[i]
        for j in range(m):
            if dr[j] <= T:
                continue
            if i == 0 and j == 0:
                cur[j] = 1
            else:
                s = prev[j]
                if j:
                    s += cur[j - 1]
                cur[j] = s % MOD
        prev = cur
    print(prev[m - 1] % MOD)

